private registerRoute(method: string, args: any[]) {
  if (this.versioningOptions?.type === VersioningType.CUSTOM) {
    for (const arg of args) {
      const metadata = arg?.[VERSIONED_ROUTE_METADATA] as
        | VersionedRouteMetadata
        | undefined;
      if (metadata) {
        this.trackCustomVersionedRoute(
          method.toUpperCase(),
          args[0],
          metadata,
        );
      }
    }
  }
  return this.instance[method](...args);
}

/**
 * Tracks a versioned handler so the custom versioning election can later
 * pick the highest registered version among the request candidates.
 */
private trackCustomVersionedRoute(
  method: string,
  path: unknown,
  metadata: VersionedRouteMetadata,
) {
  if (!isString(path)) {
    return;
  }
  const versions = (
    Array.isArray(metadata.version) ? metadata.version : [metadata.version]
  ).filter(isString);
  if (!versions.length) {
    return;
  }
  let routes = this.customVersionedRoutes.get(method);
  if (!routes) {
    routes = [];
    this.customVersionedRoutes.set(method, routes);
  }
  let route = routes.find(entry => entry.path === path);
  if (!route) {
    route = {
      path,
      regexp: pathToRegexp(path),
      handlersByVersion: new Map(),
    };
    routes.push(route);
  }
  for (const version of versions) {
    // Keep the first handler registered for a version, mirroring the
    // first-match-wins behavior of the underlying router.
    if (!route.handlersByVersion.has(version)) {
      route.handlersByVersion.set(version, metadata.handler);
    }
  }
}

private getCustomVersionedRoutes(
  method: string,
): CustomVersionedRoute[] | undefined {
  const routes = this.customVersionedRoutes.get(method) ?? [];
  // Routes registered through "all" respond to every HTTP method, and
  // Express dispatches HEAD requests to GET handlers when no HEAD handler
  // is registered; mirror both behaviors for the version election.
  const allRoutes = this.customVersionedRoutes.get('ALL') ?? [];
  const headFallbackRoutes =
    method === 'HEAD' ? (this.customVersionedRoutes.get('GET') ?? []) : [];
  const merged = [...routes, ...allRoutes, ...headFallbackRoutes];
  return merged.length ? merged : undefined;
}

