import { Controller, Get, INestApplication, VersioningType } from '@nestjs/common';
import { Test } from '@nestjs/testing';
import request from 'supertest';

@Controller({ version: '1' })
class V1Controller {
  @Get('/')
  hello() {
    return 'V1';
  }
}

@Controller({ version: '2' })
class V2Controller {
  @Get('/')
  hello() {
    return 'V2';
  }
}

describe('debug custom versioning', () => {
  it('works', async () => {
    const moduleRef = await Test.createTestingModule({
      controllers: [V1Controller, V2Controller],
    }).compile();
    const app: INestApplication = moduleRef.createNestApplication();
    app.enableVersioning({
      type: VersioningType.CUSTOM,
      extractor: (req: any) => req.headers['x-version'] ?? [],
    });
    await app.init();

    const adapter: any = app.getHttpAdapter();
    console.log('versioningOptions:', adapter.versioningOptions);
    console.log(
      'tracked:',
      [...adapter.customVersionedRoutes.entries()].map(([m, routes]) => [
        m,
        routes.map((r: any) => [r.path, [...r.handlersByVersion.keys()]]),
      ]),
    );

    await request(app.getHttpServer()).get('/').set('x-version', '1').expect(200);
    await app.close();
  });
});

